SELECT g.TMDL_BASIN, g.BBP_SYS_ID, g.TYPE, t.report_date, t.precip_mm, t.precip_in, t.n_hours, t.n_hours_expected, g.geom FROM ST_Read('https://raw.githubusercontent.com/rsignell/buzzards-bay-precip/main/basins/bbnep_subbasins_2026_v2.geojson') g JOIN 'https://r2-pub.openscicomp.io/buzzards-bay-precip/basins_v2_precip_ts.parquet' t ON g.BBP_SYS_ID || '_' || g.TYPE = t.basin_id WHERE t.report_date BETWEEN DATE '2026-09-08' AND DATE '2026-09-21' AND g.TYPE = 'WATER'
